#!/usr/bin/env python3
from pathlib import Path

p=Path('index.html')
s=p.read_text(encoding='utf-8')

if 'PILOTO v0.12 web' in s:
    print('v0.12 já aplicada')
    raise SystemExit(0)
if 'PILOTO v0.11 web' not in s:
    raise SystemExit('Versão esperada v0.11 não encontrada')

s=s.replace('PILOTO v0.11 web','PILOTO v0.12 web',1)

css=r'''
.money-subtabs{display:flex;gap:8px;flex-wrap:wrap;margin:12px 0 16px}.money-subtabs button{border:1px solid var(--line);background:#fff;color:var(--ink);padding:10px 13px;border-radius:10px;font-weight:700;cursor:pointer}.money-subtabs button.active{background:var(--accent);color:#fff;border-color:var(--accent)}.money-subpanel{display:none}.money-subpanel.active{display:block}.emenda-charts{display:grid;grid-template-columns:1fr 1fr;gap:18px;margin:14px 0}.mini-bars{display:grid;gap:10px}.mini-row{display:grid;grid-template-columns:minmax(120px,220px) 1fr 120px;gap:9px;align-items:center;font-size:12px}.mini-track{height:16px;background:var(--soft);border-radius:5px;overflow:hidden}.mini-track i{display:block;height:100%;background:var(--accent)}.table-scroll{overflow-x:auto;-webkit-overflow-scrolling:touch}.table-scroll table{min-width:760px}.emenda-controls{display:grid;grid-template-columns:180px 180px;gap:8px;margin:10px 0}.emenda-controls select{padding:10px;border:1px solid var(--line);border-radius:10px;background:#fff;font-size:14px}@media(max-width:800px){.emenda-charts{grid-template-columns:1fr}.mini-row{grid-template-columns:1fr}.mini-row .money{text-align:left}.emenda-controls{grid-template-columns:1fr}}
'''
s=s.replace('</style>',css+'</style>',1)

helpers=r'''
const UF_REGION={AC:'Norte',AP:'Norte',AM:'Norte',PA:'Norte',RO:'Norte',RR:'Norte',TO:'Norte',AL:'Nordeste',BA:'Nordeste',CE:'Nordeste',MA:'Nordeste',PB:'Nordeste',PE:'Nordeste',PI:'Nordeste',RN:'Nordeste',SE:'Nordeste',DF:'Centro-Oeste',GO:'Centro-Oeste',MT:'Centro-Oeste',MS:'Centro-Oeste',ES:'Sudeste',MG:'Sudeste',RJ:'Sudeste',SP:'Sudeste',PR:'Sul',RS:'Sul',SC:'Sul'};
function emendaRegion(localidade){const raw=(localidade||'').toString(),n=strip(raw);if(n.includes('nacional'))return 'Nacional';if(n.includes('multiplo')||n.includes('multiplas'))return 'Múltiplas localidades';const up=raw.toUpperCase(),ufs=Object.keys(UF_REGION);const uf=ufs.find(x=>new RegExp('(?:^|[^A-Z])'+x+'(?:$|[^A-Z])').test(up));return uf?UF_REGION[uf]:'Não identificado'}
function aggregateEmendas(rows,keyFn,field){const m=new Map();rows.forEach(e=>{const k=keyFn(e)||'Não informado',v=Number(e[field]||0);m.set(k,(m.get(k)||0)+v)});return [...m.entries()].map(([categoria,valor])=>({categoria,valor})).filter(x=>x.valor>0).sort((a,b)=>b.valor-a.valor)}
function barsHtml(items,total){if(!items.length||!total)return '<div class="muted">Sem valores para esta seleção.</div>';const max=Math.max(...items.map(x=>x.valor),1);return `<div class="mini-bars">${items.map(x=>`<div class="mini-row"><div>${esc(x.categoria)}</div><div class="mini-track"><i style="width:${(100*x.valor/max).toFixed(2)}%"></i></div><div class="money">${money(x.valor)} · ${(100*x.valor/total).toFixed(1).replace('.',',')}%</div></div>`).join('')}</div>`}
'''
s=s.replace('function render(D){',helpers+'\nfunction render(D){',1)

start=s.index(" const areas=Object.entries(er.por_area||{});")
end=s.index(" const cats=F.filter",start)
block=r''' const areas=Object.entries(er.por_area||{});
 if(GO&&Array.isArray(GO.por_ano)){
  const emendaYears=[...new Set(E.map(e=>e.ano).filter(Boolean))].sort((a,b)=>b-a);
  document.getElementById('dinheiro').innerHTML=`<h2>Dinheiro público</h2><div class="notice"><b>Dois fluxos separados.</b> Gastos do mandato no Senado e emendas parlamentares aparecem em painéis diferentes. A base de emendas ainda é uma amostra; por isso os gráficos de emendas também são identificados como amostra.</div><div class="money-subtabs"><button type="button" class="active" data-money="mandato">Gastos do mandato no Senado</button><button type="button" data-money="emendas">Emendas parlamentares</button></div><div id="money-mandato" class="money-subpanel active"><div class="notice oknote"><b>Gastos do mandato no Senado — 2019 a 2026.</b> Valores coletados diretamente da API oficial do Senado e atualizados automaticamente. O ano de 2026 é parcial. A soma reúne CEAPS e os gastos não inclusos na CEAPS exibidos pelo Senado; não representa o custo integral do mandato.</div><div class="money-summary"><div class="record"><span class="source">CEAPS no período</span><b>${money(GO.total_ceaps_periodo)}</b></div><div class="record"><span class="source">Fora da CEAPS exibidos</span><b>${money(GO.total_fora_ceaps_periodo)}</b></div><div class="record"><span class="source">Soma das duas seções</span><b>${money(GO.total_mostrado_periodo)}</b></div></div><div class="source">Atualizado em ${esc(fmtDateTime(GO.atualizado_em_utc))}. *2026 parcial e sujeito a novos lançamentos, ajustes ou estornos.</div><h3>Evolução anual dos recursos exibidos</h3>${expenseTrendHtml(GO.por_ano)}<h3>Composição por categoria</h3><div class="money-controls"><select id="expenseYear"><option value="periodo">Período 2019–2026</option>${GO.por_ano.slice().reverse().map(x=>`<option value="${x.ano}">${x.ano}${x.parcial?' (parcial)':''}</option>`).join('')}</select><select id="expenseGroup"><option value="ceaps">CEAPS</option><option value="fora">Gastos fora da CEAPS exibidos</option></select></div><div id="expenseChart"></div><div id="expenseTable"></div><div id="expenseSource" class="source-actions"></div></div><div id="money-emendas" class="money-subpanel"><div class="notice">As emendas carregadas ainda são uma <b>amostra</b> e não representam o total destinado no mandato. Os gráficos abaixo mostram somente os registros já carregados.</div><div class="money-summary"><div class="record"><span class="source">Empenhado na amostra</span><b>${money(er.empenhado)}</b></div><div class="record"><span class="source">Pago na amostra</span><b>${money(er.pago)}</b></div><div class="record"><span class="source">Registros carregados</span><b>${E.length}</b></div></div><div class="emenda-controls"><select id="emendaYear"><option value="">Todos os anos carregados</option>${emendaYears.map(y=>`<option value="${y}">${y}</option>`).join('')}</select><select id="emendaMetric"><option value="empenhado">Valor empenhado</option><option value="pago">Valor pago</option></select></div><div id="emendaSummary" class="source"></div><div class="emenda-charts"><div><h3>Por área apoiada</h3><div id="emendaAreaChart"></div></div><div><h3>Por região destinatária</h3><div id="emendaRegionChart"></div><div class="source">A região é derivada da UF informada na localidade. Registros nacionais, múltiplos ou sem UF permanecem separados.</div></div></div><h3>Emendas carregadas</h3><div class="table-scroll"><table><thead><tr><th>Ano</th><th>Área</th><th>Localidade</th><th>Região</th><th>Empenhado</th><th>Pago</th><th>Fonte</th></tr></thead><tbody id="emendaRows"></tbody></table></div></div>`;
  const renderExpense=()=>{const y=document.getElementById('expenseYear').value,g=document.getElementById('expenseGroup').value;let items,total,label,source='https://www12.senado.leg.br/dados-abertos/administrativo/senadores/cotas-para-exercicio-da-atividade-parlamentar';if(y==='periodo'){items=g==='ceaps'?GO.agregado_ceaps:GO.agregado_fora_ceaps;total=g==='ceaps'?GO.total_ceaps_periodo:GO.total_fora_ceaps_periodo;label=(g==='ceaps'?'CEAPS':'Fora da CEAPS')+' · 2019–2026'}else{const row=GO.por_ano.find(x=>String(x.ano)===y);items=g==='ceaps'?row.ceaps:row.fora_ceaps;total=g==='ceaps'?row.total_ceaps:row.total_fora_ceaps;label=(g==='ceaps'?'CEAPS':'Fora da CEAPS')+' · '+y+(row.parcial?' parcial':'');source=row.fonte_visual}document.getElementById('expenseChart').innerHTML=donutHtml(items,total,label);document.getElementById('expenseTable').innerHTML=expenseRowsTable(items,total);document.getElementById('expenseSource').innerHTML=`<a class="btn" href="${esc(source)}" target="_blank" rel="noopener">Abrir fonte oficial do Senado</a>`};
  const renderEmendas=()=>{const y=document.getElementById('emendaYear').value,field=document.getElementById('emendaMetric').value;const rows=E.filter(e=>!y||String(e.ano)===y);const total=rows.reduce((a,e)=>a+Number(e[field]||0),0),byArea=aggregateEmendas(rows,e=>e.funcao||'Não informado',field),byRegion=aggregateEmendas(rows,e=>emendaRegion(e.localidade),field);document.getElementById('emendaSummary').textContent=`${rows.length} registro(s) · ${field==='empenhado'?'empenhado':'pago'}: ${money(total)}`;document.getElementById('emendaAreaChart').innerHTML=barsHtml(byArea,total);document.getElementById('emendaRegionChart').innerHTML=donutHtml(byRegion,total,(field==='empenhado'?'Empenhado':'Pago')+(y?' · '+y:' · amostra'));document.getElementById('emendaRows').innerHTML=rows.slice().sort((a,b)=>Number(b.ano)-Number(a.ano)||Number(b.empenhado)-Number(a.empenhado)).map(e=>`<tr><td>${esc(e.ano)}</td><td><b>${esc(e.funcao)}</b><br><span class="source">${esc(e.descricao||'')}</span></td><td>${esc(e.localidade)}</td><td>${esc(emendaRegion(e.localidade))}</td><td class="money">${money(e.empenhado)}</td><td class="money">${money(e.pago)}</td><td><a href="${esc(e.url)}" target="_blank" rel="noopener">Fonte</a></td></tr>`).join('')};
  document.querySelectorAll('.money-subtabs button').forEach(b=>b.onclick=()=>{document.querySelectorAll('.money-subtabs button').forEach(x=>x.classList.remove('active'));document.querySelectorAll('.money-subpanel').forEach(x=>x.classList.remove('active'));b.classList.add('active');document.getElementById('money-'+b.dataset.money).classList.add('active')});
  document.getElementById('expenseYear').onchange=renderExpense;document.getElementById('expenseGroup').onchange=renderExpense;document.getElementById('emendaYear').onchange=renderEmendas;document.getElementById('emendaMetric').onchange=renderEmendas;renderExpense();renderEmendas();
 }else{
  document.getElementById('dinheiro').innerHTML=`<h2>Dinheiro público</h2><div class="notice">Base oficial de gastos do mandato indisponível nesta carga.</div>`;
 }
'''
s=s[:start]+block+s[end:]

p.write_text(s,encoding='utf-8')
print('v0.12 aplicada ao index.html')
